import React, { useEffect } from "react";
import { useparams } from "react-router-dom";
import axios from "axios"

const post = () => {
  let { id } = useparams();

  useEffect(()=>{
    axios.get(`http://localhost:3003/posts/byId`).then((response) => {
      setlistofposts(response.data);
    });
  })
  return <div>{id}</div>;
};

export default post;
